      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.TEXT)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('compressed payload')
      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(callback).toHaveBeenCalled()
    })

    it('decompresses an uncompressed frame when the extension is negotiated but RSV1 is clear', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())

      const callback = feed(parser, buildFrame({
        opcode: opcodes.TEXT,
        rsv1: false,
        payload: Buffer.from('plain payload')
      }))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('plain payload')
    })

    it('fails with 1007 when the compressed payload cannot be inflated', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())
      const garbage = Buffer.from([0xff, 0xff, 0xff, 0xff, 0xff, 0xff])

      feed(parser, buildFrame({ opcode: opcodes.TEXT, rsv1: true, payload: garbage }))

      await waitFor(() => closeFramesWrittenTo(handler).length === 1)

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1007)
    })

    it('fails with 1009 when the decompressed message exceeds the payload limit', async () => {
      const { handler, parser } = createParser({ maxPayloadSize: 100 }, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x41))
      expect(compressed.length).toBeLessThanOrEqual(100)

      feed(parser, buildFrame({ opcode: opcodes.TEXT, rsv1: true, payload: compressed }))

      await waitFor(() => closeFramesWrittenTo(handler).length === 1)

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1009)
      expect(frames[0].payload.subarray(2).toString()).toBe('Max decompressed message size exceeded')
    })

    it('decompresses large payloads when the payload limit is disabled', async () => {
      const { handler, parser } = createParser({ maxPayloadSize: 0 }, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x41))

      feed(parser, buildFrame({ opcode: opcodes.BINARY, rsv1: true, payload: compressed }))

      await waitFor(() => handler.onMessage.mock.calls.length === 1)

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.BINARY)
      expect(handler.onMessage.mock.calls[0][1].length).toBe(1000)
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })
  })
})
